.version 8.3
.target sm_89
.address_size 64
.visible .entry conv_transpose2d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 output_ptr,
    .param .s32 total
)
{
    .reg .u64 %rd<20>;
    .reg .u32 %r<64>;
    .reg .f32 %f<10>;
    .reg .pred %p<10>;
    .shared .align 4 .f32 smem_w[120];
    ld.param.u64 %rd0, [input_ptr];
    ld.param.u64 %rd1, [weight_ptr];
    ld.param.u64 %rd2, [output_ptr];
    ld.param.s32 %r0, [total];
    cvta.to.global.u64 %rd0, %rd0;
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    mov.u32 %r1, %ctaid.x;      // bidx = n*OC+oc
    mov.u32 %r2, %ntid.x;       // blockDim.x
    mov.u32 %r3, %tid.x;        // threadIdx.x
    div.u32 %r4, %r1, 64;       // n
    rem.u32 %r5, %r1, 64;       // oc
    div.u32 %r6, %r5, 16;       // group
    rem.u32 %r7, %r5, 16;       // oc_local
    mul.lo.u32 %r8, %r6, 8;     // ic_start
    mov.u32 %r9, %r3;           // t = tid.x
