    @%p0 bra LOAD_DONE;
    div.u32 %r10, %r9, 15;      // icl
    rem.u32 %r11, %r9, 15;      // rem15
    div.u32 %r12, %r11, 5;      // kh
    rem.u32 %r13, %r11, 5;      // kw
    add.u32 %r14, %r8, %r10;    // ic
    mul.lo.u32 %r15, %r14, 16;
    add.u32 %r15, %r15, %r7;
    mul.lo.u32 %r15, %r15, 3;
    add.u32 %r15, %r15, %r12;
    mul.lo.u32 %r15, %r15, 5;
    add.u32 %r15, %r15, %r13;    // weight_idx
    mul.wide.u32 %rd3, %r15, 4;
    add.u64 %rd4, %rd1, %rd3;
    ld.global.f32 %f1, [%rd4];
    mul.lo.u32 %r16, %r9, 4;
    mov.u32 %r17, smem_w;
    add.u32 %r17, %r17, %r16;
    st.shared.f32 [%r17], %f1;
    add.u32 %r9, %r9, %r2;      // t += blockDim.x
    bra LOAD_LOOP;
