    setp.ge.u32 %p1, %r20, 196862;
    @%p1 bra SPATIAL_DONE;
    div.u32 %r21, %r20, 766;    // oh
    rem.u32 %r22, %r20, 766;    // ow
    mov.f32 %f0, 0f00000000;
    mov.u32 %r23, 0;            // icl
