    add.s32 %r27, %r21, 1;      // oh+pad_h
    sub.s32 %r28, %r27, %r26;   // numerator_h
    setp.lt.s32 %p4, %r28, 0;
    @%p4 bra SKIP_KH2;
    rem.s32 %r29, %r28, 2;
    setp.ne.s32 %p5, %r29, 0;
    @%p5 bra SKIP_KH2;
    div.s32 %r30, %r28, 2;      // ih
    setp.ge.s32 %p6, %r30, 128;
    @%p6 bra SKIP_KH2;
    mov.u32 %r31, 0;            // kw
KW_LOOP:
    setp.ge.u32 %p7, %r31, 5;
    @%p7 bra KW_DONE;
    mul.lo.s32 %r32, %r31, 1;
    add.s32 %r33, %r22, 2;
    sub.s32 %r34, %r33, %r32;
    setp.lt.s32 %p8, %r34, 0;
    @%p8 bra SKIP_KW2;
    rem.s32 %r35, %r34, 3;
    setp.ne.s32 %p9, %r35, 0;
    @%p9 bra SKIP_KW2;
    div.s32 %r36, %r34, 3;      // iw
    setp.ge.s32 %p0, %r36, 256;
    @%p0 bra SKIP_KW2;
    mul.lo.u32 %r37, %r4, 32;
    add.u32 %r37, %r37, %r24;
    mul.lo.u32 %r37, %r37, 128;
    add.u32 %r37, %r37, %r30;
    mul.lo.u32 %r37, %r37, 256;
    add.u32 %r37, %r37, %r36;
    mul.wide.u32 %rd5, %r37, 4;
    add.u64 %rd6, %rd0, %rd5;
    ld.global.f32 %f2, [%rd6];
    mul.lo.u32 %r38, %r23, 15;
    mul.lo.u32 %r39, %r25, 5;
    add.u32 %r38, %r38, %r39;
    add.u32 %r38, %r38, %r31;
    mul.lo.u32 %r38, %r38, 4;
    mov.u32 %r40, smem_w;
    add.u32 %r40, %r40, %r38;
    ld.shared.f32 %f3, [%r40];
    fma.rn.f32 %f0, %f2, %f3, %f0;
SKIP_KW2:
    add.u32 %r31, %r31, 1;
    bra KW_LOOP;
KW_DONE:
SKIP_KH2:
    add.u32 %r25, %r25, 1;
    bra KH_LOOP;
KH_DONE:
    add.u32 %r23, %r23, 1;
    bra IC_LOOP;
IC_DONE:
    mul.lo.u32 %r41, %r1, 257;
    add.u32 %r41, %r41, %r21;
    mul.lo.u32 %r41, %r41, 766;
    add.u32 %r41, %r41, %r22;
    mul.wide.u32 %rd7, %r41, 4;
    add.u64 %rd8, %rd2, %rd7;
    st.global.f32 [%rd8], %f0;
    add.u32 %r20, %r20, %r2;
    bra SPATIAL_LOOP;
SPATIAL_DONE:
    ret;
}
