        OW = (IW - 1) * sW - 2 * pW + dW * (kW - 1) + 1

        output = torch.empty((N, OC, OH, OW), dtype=x.dtype, device=x.device)

        total = N * OC * OH * OW

        module = _get_ptx_module()

        block = (256, 1, 1)
        grid = (N * OC, 1, 1)

        module.launch(
            "conv_transpose2d_kernel",
            grid=grid,
            block=block,
            arguments=[x, weight, output, i32(total)],
            shared_memory=480,
            stream=torch.cuda.current_stream(x.device),
        )

